import type {
  WeatherCondition,
  WeatherUnits,
} from "@/features/weather/weather-schema";

/**
The two ways the card reads the days ahead: the next 24 hours, or the next ten days.
*/
export const FORECAST_VIEWS = ["hourly", "daily"] as const;
export type ForecastView = (typeof FORECAST_VIEWS)[number];

export const FORECAST_VIEW_LABEL: Record<ForecastView, string> = {
  daily: "10-day",
  hourly: "Hourly",
};

export function isForecastView(value: unknown): value is ForecastView {
  return (FORECAST_VIEWS as readonly unknown[]).includes(value);
}

export interface ForecastHour {
  /**
  Unix time in milliseconds the hour starts at.
  */
  time: number;
  temperature: number;
  condition: WeatherCondition;
  isDay: boolean;
  /**
  Chance of rain or snow in the hour, 0 to 100.
  */
  precipitation: number;
}

export interface ForecastDay {
  /**
  Unix time in milliseconds of the day's local midnight.
  */
  time: number;
  high: number;
  low: number;
  condition: WeatherCondition;
  /**
  Highest chance of rain or snow in the day, 0 to 100.
  */
  precipitation: number;
}

export interface ForecastData {
  /**
  The place's name, e.g. "Austin".
  */
  location: string;
  /**
  The state or region and country, e.g. "Texas, United States".
  */
  region: string;
  /**
  IANA time zone of the place. Hours and days read in it.
  */
  timeZone: string;
  units: WeatherUnits;
  /**
  The weather right now, for the header.
  */
  current: {
    temperature: number;
    condition: WeatherCondition;
    label: string;
    isDay: boolean;
  };
  /**
  Every hour of the next 24, starting with the current one.
  */
  hours: ForecastHour[];
  /**
  The next ten days, starting with today.
  */
  days: ForecastDay[];
  /**
  Unix time in milliseconds of the reading.
  */
  asOf: number;
}

/**
The hours the hourly view shows: every second hour of the next 24, so twelve fit in two rows.
*/
export const HOUR_STEP = 2;

/**
The first one is "Now", so it takes the current reading, the same one the header shows, over the forecast for the whole hour.
*/
export function shownHours(data: ForecastData): ForecastHour[] {
  return data.hours
    .filter((_, index) => index % HOUR_STEP === 0)
    .map((hour, index) =>
      index === 0
        ? {
            ...hour,
            condition: data.current.condition,
            isDay: data.current.isDay,
            temperature: data.current.temperature,
          }
        : hour
    );
}

/**
"Now" for the current hour, then "3 PM", in the place's own time zone.
*/
export function formatForecastHour(
  hour: ForecastHour,
  index: number,
  timeZone: string
): string {
  if (index === 0) {
    return "Now";
  }
  const format = new Intl.DateTimeFormat("en-US", {
    hour: "numeric",
    timeZone,
  });
  return format.format(hour.time);
}

/**
"Today" for the first day, then "Wed", in the place's own time zone.
*/
export function formatForecastDay(
  day: ForecastDay,
  index: number,
  timeZone: string
): string {
  if (index === 0) {
    return "Today";
  }
  const format = new Intl.DateTimeFormat("en-US", {
    timeZone,
    weekday: "short",
  });
  return format.format(day.time);
}

/**
A chance of rain or snow worth showing: lower chances read as noise.
*/
export const RAIN_SHOWN_FROM = 20;

/**
A chance of rain or snow the summary calls likely.
*/
const RAIN_LIKELY_FROM = 50;

function extremes(values: readonly number[]) {
  return { max: Math.max(...values), min: Math.min(...values) };
}

/**
One sentence the model (or a screen reader) can use to describe the card in a view.
*/
export function summarizeForecast(
  data: ForecastData,
  view: ForecastView
): string {
  const unit = data.units === "f" ? "F" : "C";
  if (view === "hourly") {
    const { max, min } = extremes(data.hours.map((hour) => hour.temperature));
    let [wettest] = data.hours;
    for (const hour of data.hours) {
      if (hour.precipitation > wettest.precipitation) {
        wettest = hour;
      }
    }
    const rain =
      wettest && wettest.precipitation >= RAIN_SHOWN_FROM
        ? ` The best chance of rain is ${wettest.precipitation}% around ${formatForecastHour(wettest, 1, data.timeZone)}.`
        : " Rain is unlikely.";
    return `${data.location} over the next 24 hours: ${formatTemperature(data.current.temperature)}${unit} now, between ${formatTemperature(min)} and ${formatTemperature(max)}.${rain}`;
  }
  const highs = extremes(data.days.map((day) => day.high));
  const lows = extremes(data.days.map((day) => day.low));
  const wetDays = data.days
    .map((day, index) => ({ day, index }))
    .filter(({ day }) => day.precipitation >= RAIN_LIKELY_FROM)
    .map(({ day, index }) => formatForecastDay(day, index, data.timeZone));
  const rain =
    wetDays.length > 0
      ? ` Rain or snow is likely on ${wetDays.join(", ")}.`
      : " Rain or snow is unlikely.";
  return `${data.location} over the next ${data.days.length} days: highs from ${formatTemperature(highs.min)} to ${formatTemperature(highs.max)}${unit}, lows from ${formatTemperature(lows.min)} to ${formatTemperature(lows.max)}.${rain}`;
}

import type { WeatherCondition } from "@/features/weather/weather-schema";

const SUN = "#FFD60A";
const RAIN = "#64D2FF";
/**
Clouds and the moon are white for the Weather card's sky. A card on a plain surface sets --weather-cloud and --weather-moon to darker tones, so they stay visible.
*/
const CLOUD = "var(--weather-cloud, #FFFFFF)";
const MOON = "var(--weather-moon, #F5F3FF)";

const CLOUD_PATH =
  "M9.6 26h13.9a6.25 6.25 0 0 0 .78-12.45A8.25 8.25 0 0 0 8.5 15.1 5.5 5.5 0 0 0 9.6 26Z";

const RAY_ANGLES = [0, 45, 90, 135, 180, 225, 270, 315] as const;

function Sun({
  cx,
  cy,
  radius,
}: {
  readonly cx: number;
  readonly cy: number;
  readonly radius: number;
}) {
  return (
    <g>
      <circle cx={cx} cy={cy} r={radius} fill={SUN} />
      {RAY_ANGLES.map((angle) => {
        const rad = (angle * Math.PI) / 180;
        const inner = radius + 2.2;
        const outer = radius + 4.6;
        return (
          <line
            key={angle}
            x1={cx + Math.cos(rad) * inner}
            y1={cy + Math.sin(rad) * inner}
            x2={cx + Math.cos(rad) * outer}
            y2={cy + Math.sin(rad) * outer}
            stroke={SUN}
            strokeWidth={2}
            strokeLinecap="round"
          />
        );
      })}
    </g>
  );
}

function Moon({
  cx,
  cy,
  radius,
}: {
  readonly cx: number;
  readonly cy: number;
  readonly radius: number;
}) {
  const r = radius;
  return (
    <path
      d={`M${cx + r * 0.35} ${cy - r}A${r} ${r} 0 1 0 ${cx + r} ${cy + r * 0.35} ${r * 0.8} ${r * 0.8} 0 0 1 ${cx + r * 0.35} ${cy - r}Z`}
      style={{ fill: MOON }}
    />
  );
}

function Cloud({
  lift = 0,
  opacity = 1,
}: {
  readonly lift?: number;
  readonly opacity?: number;
}) {
  return (
    <path
      d={CLOUD_PATH}
      style={{ fill: CLOUD }}
      opacity={opacity}
      transform={lift ? `translate(0 ${-lift})` : undefined}
    />
  );
}

function Precipitation({
  condition,
}: {
  readonly condition: WeatherCondition;
}) {
  if (condition === "rain") {
    return (
      <g stroke={RAIN} strokeWidth={2} strokeLinecap="round">
        <line x1={11} y1={25} x2={9.5} y2={29} />
        <line x1={16.5} y1={25} x2={15} y2={29} />
        <line x1={22} y1={25} x2={20.5} y2={29} />
      </g>
    );
  }
  if (condition === "drizzle") {
    return (
      <g fill={RAIN}>
        <circle cx={11} cy={26.5} r={1.2} />
        <circle cx={16.5} cy={28} r={1.2} />
        <circle cx={22} cy={26.5} r={1.2} />
      </g>
    );
  }
  if (condition === "snow") {
    return (
      <g style={{ fill: CLOUD }}>
        <circle cx={11} cy={26} r={1.5} />
        <circle cx={16.5} cy={28.5} r={1.5} />
        <circle cx={22} cy={26} r={1.5} />
      </g>
    );
  }
  if (condition === "thunderstorm") {
    return <path d="M17.5 21 13 27.5h3.4L15 32l5-7h-3.6l1.6-4Z" fill={SUN} />;
  }
  if (condition === "fog") {
    return (
      <g
        style={{ stroke: CLOUD }}
        strokeWidth={2}
        strokeLinecap="round"
        opacity={0.85}
      >
        <line x1={7} y1={25.5} x2={25} y2={25.5} />
        <line x1={10} y1={29.5} x2={22} y2={29.5} />
      </g>
    );
  }
  return null;
}

export function WeatherIcon({
  condition,
  isDay = true,
  size = 24,
  className,
}: {
  readonly condition: WeatherCondition;
  readonly isDay?: boolean;
  readonly size?: number;
  readonly className?: string;
}) {
  let glyph;
  switch (condition) {
    case "clear": {
      glyph = isDay ? (
        <Sun cx={16} cy={16} radius={6.5} />
      ) : (
        <Moon cx={15} cy={16} radius={9} />
      );

      break;
    }
    case "partly-cloudy": {
      glyph = (
        <>
          {isDay ? (
            <Sun cx={12} cy={11} radius={5} />
          ) : (
            <Moon cx={12} cy={10.5} radius={6.5} />
          )}
          <g transform="translate(4 3) scale(0.85)">
            <Cloud />
          </g>
        </>
      );

      break;
    }
    case "cloudy": {
      glyph = <Cloud lift={2} />;

      break;
    }
    default: {
      glyph = (
        <>
          <Cloud lift={condition === "thunderstorm" ? 6 : 5} />
          <Precipitation condition={condition} />
        </>
      );
    }
  }

  return (
    <svg
      viewBox="0 0 32 32"
      width={size}
      height={size}
      aria-hidden
      className={className}
    >
      {glyph}
    </svg>
  );
}

import "server-only";
import {
  defaultUnits,
  describeWeatherCode,
} from "@/features/weather/weather-schema";
import type {
  WeatherData,
  WeatherUnits,
} from "@/features/weather/weather-schema";

export interface GeocodeResult {
  name: string;
  latitude: number;
  longitude: number;
  country?: string;
  country_code?: string;
  admin1?: string;
}

interface Forecast {
  utc_offset_seconds: number;
  timezone: string;
  current: {
    time: string;
    temperature_2m: number;
    weather_code: number;
    is_day: number;
  };
  daily: {
    temperature_2m_max: number[];
    temperature_2m_min: number[];
    sunrise: string[];
    sunset: string[];
  };
}

export class LocationNotFoundError extends Error {
  constructor(location: string, options?: ErrorOptions) {
    super(`Couldn't find a place called "${location}".`, options);
    this.name = "LocationNotFoundError";
  }
}

/**
The place a name means, narrowed by the region or country after a comma ("Paris, Texas").
*/
export async function geocode(location: string): Promise<GeocodeResult> {
  const [name, ...rest] = location.split(",").map((part) => part.trim());
  const qualifier = rest.join(" ").toLowerCase();
  const url = `https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(name)}&count=10&language=en&format=json`;

  const response = await fetch(url);
  if (!response.ok) {
    throw new Error(`The geocoding service returned ${response.status}.`);
  }
  const { results } = (await response.json()) as {
    results?: GeocodeResult[];
  };
  if (!results?.length) {
    throw new LocationNotFoundError(location);
  }
  const narrowed = qualifier
    ? results.find((result) =>
        [result.admin1, result.country, result.country_code].some(
          (field) => field && qualifier.includes(field.toLowerCase())
        )
      )
    : undefined;
  return narrowed ?? results[0];
}

/**
Open-Meteo's local times ("2026-10-14T15:00") as Unix milliseconds.
*/
export function toUnix(localTime: string, offsetSeconds: number) {
  return Date.parse(`${localTime}Z`) - offsetSeconds * 1000;
}

/**
The live weather for a place. Units follow the place unless given.
*/
export async function getWeather(
  location: string,
  units?: WeatherUnits
): Promise<WeatherData> {
  const place = await geocode(location);
  const unit = units ?? defaultUnits(place.country_code);
  const parameters = new URLSearchParams({
    current: "temperature_2m,weather_code,is_day",
    daily: "temperature_2m_max,temperature_2m_min,sunrise,sunset",
    forecast_days: "1",
    latitude: String(place.latitude),
    longitude: String(place.longitude),
    temperature_unit: unit === "f" ? "fahrenheit" : "celsius",
    timezone: "auto",
  });

  const response = await fetch(
    `https://api.open-meteo.com/v1/forecast?${parameters}`
  );
  if (!response.ok) {
    throw new Error(`The weather service returned ${response.status}.`);
  }
  const forecast = (await response.json()) as Forecast;
  const offset = forecast.utc_offset_seconds;
  const { current, daily } = forecast;

  const asOf = toUnix(current.time, offset);
  const isDay = current.is_day === 1;
  const now = describeWeatherCode(current.weather_code, isDay);

  return {
    asOf,
    condition: now.condition,
    fake: false,
    high: daily.temperature_2m_max[0],
    isDay,
    label: now.label,
    location: place.name,
    low: daily.temperature_2m_min[0],
    region: [place.admin1, place.country].filter(Boolean).join(", "),
    sunrise: toUnix(daily.sunrise[0], offset),
    sunset: toUnix(daily.sunset[0], offset),
    temperature: current.temperature_2m,
    timeZone: forecast.timezone,
    units: unit,
  };
}

export const WEATHER_UNITS = ["f", "c"] as const;
export type WeatherUnits = (typeof WEATHER_UNITS)[number];

/**
What the sky is doing, at the detail the card draws it.
*/
export const WEATHER_CONDITIONS = [
  "clear",
  "partly-cloudy",
  "cloudy",
  "fog",
  "drizzle",
  "rain",
  "snow",
  "thunderstorm",
] as const;
export type WeatherCondition = (typeof WEATHER_CONDITIONS)[number];

/**
Where the sun is: the light the sky is painted in.
*/
export const SKY_PHASES = [
  "night",
  "dawn",
  "sunrise",
  "day",
  "golden-hour",
  "sunset",
  "dusk",
] as const;
export type SkyPhase = (typeof SKY_PHASES)[number];

export const SKY_PHASE_LABEL: Record<SkyPhase, string> = {
  dawn: "Dawn",
  day: "Day",
  dusk: "Dusk",
  "golden-hour": "Golden hour",
  night: "Night",
  sunrise: "Sunrise",
  sunset: "Sunset",
};

export interface WeatherData {
  /**
  The place's name, e.g. "New York".
  */
  location: string;
  /**
  The state or region and country, e.g. "New York, United States".
  */
  region: string;
  /**
  IANA time zone of the place, e.g. "America/New_York".
  */
  timeZone: string;
  units: WeatherUnits;
  temperature: number;
  condition: WeatherCondition;
  /**
  e.g. "Mostly Cloudy": finer than `condition`.
  */
  label: string;
  isDay: boolean;
  high: number;
  low: number;
  /**
  Unix times in milliseconds of today's sunrise and sunset there.
  */
  sunrise: number;
  sunset: number;
  /**
  Unix time in milliseconds of the reading.
  */
  asOf: number;
  /**
  True when this is generated data, not a live forecast.
  */
  fake: boolean;
}

/** The condition and label for a WMO weather code (what Open-Meteo returns).
 *  https://open-meteo.com/en/docs#weather_variable_documentation */
export function describeWeatherCode(
  code: number,
  isDay: boolean
): { condition: WeatherCondition; label: string } {
  if (code === 0) {
    return { condition: "clear", label: isDay ? "Sunny" : "Clear" };
  }
  if (code === 1) {
    return {
      condition: "clear",
      label: isDay ? "Mostly Sunny" : "Mostly Clear",
    };
  }
  if (code === 2) {
    return { condition: "partly-cloudy", label: "Partly Cloudy" };
  }
  if (code === 3) {
    return { condition: "cloudy", label: "Mostly Cloudy" };
  }
  if (code === 45 || code === 48) {
    return { condition: "fog", label: "Foggy" };
  }
  if (code >= 51 && code <= 57) {
    return { condition: "drizzle", label: "Drizzle" };
  }
  if (code === 66 || code === 67) {
    return { condition: "rain", label: "Freezing Rain" };
  }
  if ((code >= 61 && code <= 65) || (code >= 80 && code <= 82)) {
    return {
      condition: "rain",
      label: code === 65 || code === 82 ? "Heavy Rain" : "Rain",
    };
  }
  if ((code >= 71 && code <= 77) || code === 85 || code === 86) {
    return { condition: "snow", label: "Snow" };
  }
  return code >= 95
    ? { condition: "thunderstorm", label: "Thunderstorms" }
    : { condition: "cloudy", label: "Cloudy" };
}

const MINUTE = 60_000;

/** The sky's phase at `time`, from that day's sunrise and sunset: a short
 *  dawn and sunrise around the first, golden hour, sunset and dusk around
 *  the second, plain day between them and night outside. */
export function skyPhase(
  time: number,
  sunrise: number,
  sunset: number
): SkyPhase {
  const fromSunrise = (time - sunrise) / MINUTE;
  const fromSunset = (time - sunset) / MINUTE;
  if (fromSunrise < -50 || fromSunset > 55) {
    return "night";
  }
  if (fromSunrise < -10) {
    return "dawn";
  }
  if (fromSunrise < 40) {
    return "sunrise";
  }
  if (fromSunset < -70) {
    return "day";
  }
  if (fromSunset < -20) {
    return "golden-hour";
  }
  return fromSunset < 15 ? "sunset" : "dusk";
}

/**
Fahrenheit where people expect it, Celsius everywhere else.
*/
export function defaultUnits(countryCode: string | undefined): WeatherUnits {
  return ["US", "LR", "MM", "BS", "BZ", "KY", "PW"].includes(
    countryCode?.toUpperCase() ?? ""
  )
    ? "f"
    : "c";
}

export function formatTemperature(value: number): string {
  return `${Math.round(value)}°`;
}

/** One sentence the model (or a screen reader) can use to describe the
 *  card. */
export function summarizeWeather(data: WeatherData): string {
  const unit = data.units === "f" ? "F" : "C";
  return `${data.location}: ${Math.round(data.temperature)}°${unit} and ${data.label.toLowerCase()}, with a high of ${Math.round(data.high)}° and a low of ${Math.round(data.low)}°.`;
}

import { getForecast } from "@/features/forecast/forecast-queries";
import { LocationNotFoundError } from "@/features/weather/weather-queries";
import { WEATHER_UNITS } from "@/features/weather/weather-schema";
import type { WeatherUnits } from "@/features/weather/weather-schema";

const CACHE = "public, s-maxage=600, stale-while-revalidate=1800";
const MAX_LOCATION_LENGTH = 100;

const BAD_REQUEST = 400;
const NOT_FOUND = 404;
const UPSTREAM_FAILED = 502;

function isUnits(value: string): value is WeatherUnits {
  return (WEATHER_UNITS as readonly string[]).includes(value);
}

// eslint-disable-next-line sonarjs/function-name -- Next.js route handlers must be named after the HTTP method
export async function GET(request: Request) {
  const { searchParams } = new URL(request.url);
  const location = searchParams.get("location")?.trim();
  const units = searchParams.get("units");

  if (
    !location ||
    location.length > MAX_LOCATION_LENGTH ||
    (units !== null && !isUnits(units))
  ) {
    return Response.json(
      { error: "Pass a location, and optionally units of f or c." },
      { status: BAD_REQUEST }
    );
  }

  const requested = units ?? undefined;
  try {
    return Response.json(await getForecast(location, requested), {
      headers: { "Cache-Control": CACHE },
    });
  } catch (error) {
    const status =
      error instanceof LocationNotFoundError ? NOT_FOUND : UPSTREAM_FAILED;
    return Response.json(
      { error: Error.isError(error) ? error.message : "Forecast failed." },
      { status }
    );
  }
}

